<div class="flex min-h-screen bg-gray-50">
  <?php require __DIR__ . '/../partials/sidebar.php'; ?>
  <main class="flex-1 px-5 py-7 md:px-8">
    <header class="mb-6"><h1 class="font-display text-2xl font-semibold text-gray-900">Return / refund</h1><p class="mt-1 text-sm text-gray-500">Request a return or refund for an item from a delivered online order.</p></header>
    <?php if (!empty($success)): ?><div class="mb-5 rounded-lg border border-teal/30 bg-teal-light px-4 py-3 text-sm text-teal"><?= htmlspecialchars($success) ?></div><?php endif; ?>
    <?php if (empty($items)): ?><div class="rounded-lg border bg-white p-10 text-center"><p class="text-sm text-gray-500">You do not have delivered items eligible for a return or refund request.</p><a href="/orders" class="mt-3 inline-flex items-center gap-1 text-sm font-semibold text-teal hover:underline"><i data-lucide="package" class="h-4 w-4"></i>View my orders</a></div><?php else: ?><div class="overflow-hidden rounded-xl border border-gray-200 bg-white"><table id="customerReturnsTable" data-datatable class="w-full text-sm"><thead><tr class="border-b text-left text-xs uppercase text-gray-500"><th class="p-3">Product</th><th class="p-3">Order</th><th class="p-3">Delivered</th><th class="p-3">Request status</th><th class="p-3">Action</th></tr></thead><tbody>
      <?php foreach ($items as $item): ?><tr class="border-b last:border-0"><td class="p-3"><div class="flex items-center gap-2"><?php if (!empty($item['image_url'])): ?><img src="/<?= htmlspecialchars($item['image_url']) ?>" alt="" class="h-9 w-9 rounded object-cover"><?php endif; ?><div><p class="font-semibold text-ink"><?= htmlspecialchars($item['product_name']) ?></p><p class="text-xs text-gray-500"><?= htmlspecialchars($item['variant_label'] ?: '—') ?></p></div></div></td><td class="p-3">#<?= (int)$item['order_number'] ?></td><td class="p-3 text-gray-500"><?= $item['delivered_at'] ? date('M j, Y', strtotime($item['delivered_at'])) : '—' ?></td><td class="p-3"><?php if (empty($item['return_status'])): ?><span class="rounded-full bg-amber-50 px-2.5 py-1 text-xs font-bold text-amber-700">No request</span><?php else: ?><span class="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700"><?= htmlspecialchars(ucfirst($item['return_status'])) ?></span><?php endif; ?></td><td class="p-3"><?php if (empty($item['return_status'])): ?><a href="/orders/item/<?= (int)$item['id'] ?>/return" class="js-postpurchase-action inline-flex items-center gap-1 rounded-lg border border-red-300 px-3 py-1.5 text-xs font-bold text-red-600 hover:bg-red-50" data-title="Request a return or refund?" data-text="You will be asked for the reason and any supporting details."><i data-lucide="rotate-ccw" class="h-4 w-4"></i>Return / refund</a><?php else: ?><span class="text-xs text-gray-400">Request sent</span><?php endif; ?></td></tr><?php endforeach; ?>
      </tbody></table></div><?php endif; ?>
