</div>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.js-postpurchase-action').forEach(function(link){link.addEventListener('click',function(event){event.preventDefault();var href=this.href;Swal.fire({title:this.dataset.title,text:this.dataset.text,icon:'question',showCancelButton:true,confirmButtonText:'Continue',cancelButtonText:'Cancel',confirmButtonColor:'#0d9488',reverseButtons:true}).then(function(result){if(result.isConfirmed)window.location.href=href;});});});});</script>
